#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long *a = (long long*)malloc(n * sizeof(long long));
    long long *res = (long long*)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    res[0] = 1;
    for (int i = 1; i < n; i++) res[i] = res[i-1] * a[i-1];
    long long suff = 1;
    for (int i = n - 1; i >= 0; i--) {
        res[i] *= suff;
        suff *= a[i];
    }
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%lld", res[i]);
    }
    putchar('\n');
    free(a); free(res);
    return 0;
}

